    const char *optstring = "vf:";

    while ((opt = getopt(argc, argv, optstring)) != -1) {
        switch (opt) {
            case 'v':
                verbose = 1;
                break;
            case 'f':
                filename = optarg;
                break;
            case '?':
                // Unknown option or missing argument
