    }

    this.remove = function(key) {
        delete map[key]
        keySet.delete(key)
    }

    this.keys = function() {
        return Array.from(keySet)
    }

    this.values = function() {
        return Array.from(keySet).map(key => map[key])
    }

    this.size = function() {
        return keySet.size
    }

    this.entries = function() {
        return Array.from(keySet).map(key => [key, map[key]])
    }

